package com.ecotwin.controller;
import com.ecotwin.model.Device;import com.ecotwin.repository.DeviceRepository;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/devices") @CrossOrigin(origins="*") public class DeviceController {private final DeviceRepository repo; public DeviceController(DeviceRepository repo){this.repo=repo;} @GetMapping public List<Device> all(){return repo.findAll();} @GetMapping("/{id}") public ResponseEntity<Device> one(@PathVariable String id){return repo.findById(id).map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());} public record CreateRequest(String name,String type,LocalDate purchaseDate){} @PostMapping public Device create(@Valid @RequestBody CreateRequest r){return repo.save(new Device(r.name(),r.type(),r.purchaseDate()==null?LocalDate.now():r.purchaseDate()));} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable String id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();}}
